script:
var HIDDEN = {{hidden}};
var CYCLES = {{cycles}};

var edgesGroup = document.getElementById('edges');
var nodesGroup = document.getElementById('nodes');
var caption = document.getElementById('caption');
var stageChip = document.getElementById('layer-chip');

// 三层：3 个输入 → HIDDEN 个隐藏 → 1 个输出
var INPUTS = [0.8, 0.3, -0.5];
var layers = [
  { x: 60, count: INPUTS.length, label: '输入' },
  { x: 230, count: HIDDEN, label: '隐藏' },
  { x: 400, count: 1, label: '输出' }
];

function nodeY(layerIndex, index, count) {
  var top = 32;
  var bottom = 190;
  if (count === 1) return (top + bottom) / 2;
  var step = (bottom - top) / (count - 1);
  return top + step * index;
}

var nodes = [];
for (var l = 0; l < layers.length; l += 1) {
  nodes.push([]);
  for (var n = 0; n < layers[l].count; n += 1) {
    var y = nodeY(l, n, layers[l].count);
    var circle = Sandbox.svgEl('circle');
    circle.setAttribute('cx', String(layers[l].x));
    circle.setAttribute('cy', String(y));
    circle.setAttribute('r', '15');
    circle.setAttribute('fill', l === 0 ? '#e8f0fd' : '#ffffff');
    circle.setAttribute('stroke', '#2f6fd0');
    circle.setAttribute('stroke-width', '1.5');
    nodesGroup.appendChild(circle);

    var label = Sandbox.svgEl('text');
    label.setAttribute('x', String(layers[l].x));
    label.setAttribute('y', String(y + 4));
    label.setAttribute('text-anchor', 'middle');
    label.setAttribute('class', 'axis-label');
    label.textContent = l === 0 ? INPUTS[n].toFixed(1) : '0'; // 中间层初值 0（还没算）
    nodesGroup.appendChild(label);
    nodes[l].push({ circle: circle, label: label, y: y });
  }

  var title = Sandbox.svgEl('text');
  title.setAttribute('x', String(layers[l].x));
  title.setAttribute('y', '14');
  title.setAttribute('text-anchor', 'middle');
  title.setAttribute('class', 'axis-label');
  title.textContent = layers[l].label + '层';
  nodesGroup.appendChild(title);
}

// 连线：输入层 → 隐藏层（每条线代表一个「权重」）
var edgePairs = [];
for (var i = 0; i < layers[0].count; i += 1) {
  for (var h = 0; h < HIDDEN; h += 1) edgePairs.push({ layer: 0, from: i, to: h });
}
for (var h2 = 0; h2 < HIDDEN; h2 += 1) edgePairs.push({ layer: 1, from: h2, to: 0 });

var edges = [];
for (var e = 0; e < edgePairs.length; e += 1) {
  var pair = edgePairs[e];
  var fromX = layers[pair.layer].x;
  var fromY = nodes[pair.layer][pair.from].y;
  var toX = layers[pair.layer + 1].x;
  var toY = nodes[pair.layer + 1][pair.to].y;
  var line = Sandbox.svgEl('line');
  line.setAttribute('x1', String(fromX));
  line.setAttribute('y1', String(fromY));
  line.setAttribute('x2', String(toX));
  line.setAttribute('y2', String(toY));
  line.setAttribute('stroke', '#d6ddec');
  line.setAttribute('stroke-width', '1.4');
  edgesGroup.appendChild(line);
  edges.push(line);
}

function activation(sum) {
  // 激活函数：把加权和压到 0..1（教学用的平滑版本，等价于 Sigmoid 的形状）
  return 1 / (1 + Math.exp(-sum));
}

function forwardValues() {
  var first = [];
  for (var h = 0; h < HIDDEN; h += 1) {
    var sum = 0;
    for (var i = 0; i < INPUTS.length; i += 1) {
      // 权重是固定的（演示用）：不同输入对每个隐藏神经元的重要性不一样
      sum += INPUTS[i] * (0.9 - 0.4 * h + 0.2 * i);
    }
    first.push(activation(sum));
  }
  var outSum = 0;
  for (var k = 0; k < first.length; k += 1) outSum += first[k] * (1.2 - 0.15 * k);
  return { hidden: first, output: activation(outSum - 1) };
}

Sandbox.play(function () {
  var values = forwardValues();
  var steps = [];

  for (var cycle = 0; cycle < CYCLES; cycle += 1) {
    // 输入层点亮
    steps.push({
      targets: nodes[0].map(function (node) { return node.circle; }),
      r: [15, 19],
      duration: 240,
      direction: 'alternate',
      begin: function () {
        stageChip.textContent = '输入层';
        caption.textContent = '输入是一组数字，比如一张图的像素、一句话的特征。';
      }
    });

    // 隐藏层：加权求和 + 激活
    for (var h = 0; h < HIDDEN; h += 1) {
      steps.push({
        targets: edges.slice(0, layers[0].count * HIDDEN),
        stroke: '#2f6fd0',
        strokeWidth: 2,
        duration: 160,
        direction: 'normal',
        begin: (function (index) {
          return function () {
            stageChip.textContent = '加权求和 + 激活';
            caption.textContent = '每个输入乘上自己的权重再相加，然后过一道激活函数，这就是一个神经元做的事。';
            nodes[1][index].label.textContent = values.hidden[index].toFixed(2);
          };
        })(h),
        complete: (function (index) {
          return function () {
            anime({
              targets: nodes[1][index].circle,
              r: [15, 19],
              fill: '#e8f0fd',
              duration: 200,
              direction: 'alternate'
            });
          };
        })(h)
      });
    }

    // 输出层
    steps.push({
      targets: edges.slice(layers[0].count * HIDDEN),
      stroke: '#1f9d63',
      strokeWidth: 2,
      duration: 220,
      begin: function () {
        stageChip.textContent = '输出层';
        caption.textContent = '隐藏层的输出再被加权求和一次，得到最后的预测值。';
        nodes[2][0].label.textContent = values.output.toFixed(2);
      },
      complete: function () {
        anime({ targets: nodes[2][0].circle, r: [15, 20], fill: '#dff5e9', stroke: '#1f9d63', duration: 260, direction: 'alternate' });
        caption.textContent = '预测值 ' + values.output.toFixed(2) + '：这就是这一轮前向传播的结果。';
      }
    });

    // 还原准备下一轮
    steps.push({
      targets: edges,
      stroke: '#d6ddec',
      strokeWidth: 1.4,
      duration: 160,
      complete: function () {
        caption.textContent = '再来一遍：同样的输入，同样的权重，结果也一样，这就是「推理」。';
      }
    });
  }

  var timeline = anime.timeline({ autoplay: true, easing: 'easeInOutSine' });
  for (var s = 0; s < steps.length; s += 1) timeline.add(steps[s]);
  timeline.play();

  var total = timeline.duration || 6000;
  return {
    pause: function () { timeline.pause(); },
    play: function () { timeline.play(); },
    restart: function () { timeline.restart(); },
    finished: {
      then: function (resolve) {
        var elapsed = 0;
        var timer = setInterval(function () {
          elapsed += 100;
          if (timeline.completed || elapsed > total + 800) {
            clearInterval(timer);
            resolve();
          }
          Sandbox.progress(Math.min(1, elapsed / total));
        }, 100);
      }
    }
  };
});

Sandbox.ready({ template: 'neural-forward', hidden: HIDDEN });
